class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        cnt = defaultdict(int)

        for i in range(n - k + 1):
            subarray = nums[i:i + k]
            for x in set(subarray):
                cnt[x] += 1

        ans = -1
        for x, c in cnt.items():
