def minPath(grid, k):
    n = len(grid)

    start = None
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                start = (r, c)
                break
        if start is not None:
            break

    ans = []
    r, c = start
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for step in range(k):
        ans.append(grid[r][c])

        if step == k - 1:
            break

        best_r, best_c = -1, -1
        best_val = n * n + 1

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                val = grid[nr][nc]
                if val < best_val:
                    best_val = val
                    best_r, best_c = nr, nc

        r, c = best_r, best_c

    return ans
