from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        size = 1
        while size < n:
            size <<= 1

        # Segment tree storing max capacity among unused baskets.
        tree = [-1] * (2 * size)

        for i, cap in enumerate(baskets):
            tree[size + i] = cap

        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[i << 1], tree[i << 1 | 1])

        def first_ge(x: int) -> int:
            if tree[1] < x:
                return -1

            node = 1
            while node < size:
                left = node << 1
                if tree[left] >= x:
                    node = left
                else:
                    node = left | 1

            return node - size

        unplaced = 0

        for x in fruits:
            idx = first_ge(x)

            if idx == -1:
                unplaced += 1
                continue

            # Mark basket as used.
            p = size + idx
            tree[p] = -1
            p >>= 1

            while p:
                tree[p] = max(tree[p << 1], tree[p << 1 | 1])
                p >>= 1

        return unplaced
