        max_g = max(groups)
        best = [-1] * (max_g + 1)
        seen = set()

        for idx, e in enumerate(elements):
            if e in seen:
                continue
            seen.add(e)

            if e > max_g:
                continue

            for multiple in range(e, max_g + 1, e):
                if best[multiple] == -1:
                    best[multiple] = idx

        return [best[g] for g in groups]
