def magic_square_test(matrix):
    if not matrix:
        return False

    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return False

    seen = set()
    for row in matrix:
        for value in row:
            if not isinstance(value, int) or isinstance(value, bool):
                return False
            if value < 1 or value > n * n or value in seen:
                return False
            seen.add(value)

    target = n * (n * n + 1) // 2

    if any(sum(row) != target for row in matrix):
        return False

    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target:
            return False

    if sum(matrix[i][i] for i in range(n)) != target:
        return False
    if sum(matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True


