class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [0] * numberOfUsers

        # Same timestamp: OFFLINE status changes happen before MESSAGE events.
        events.sort(key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        for typ, timestamp, data in events:
            t = int(timestamp)

            if typ == "OFFLINE":
                uid = int(data)
                offline_until[uid] = t + 60

            else:
                if data == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1

                elif data == "HERE":
                    for i in range(numberOfUsers):
                        if offline_until[i] <= t:
                            mentions[i] += 1

                else:
                    for token in data.split():
                        uid = int(token[2:])  # token is like "id<number>"
                        mentions[uid] += 1

        return mentions
